-- Запись журнала «Новости платформы»: импорт товара с новых сайтов поставщиков (01.10.2026).
INSERT INTO "PlatformNews" ("id", "title", "body", "publishedAt", "updatedAt") VALUES
    ('news_20261001_import_evrosid',
     'Импорт товара работает ещё с четырьмя сайтами поставщиков',
     'В «Товарах» в окне «Импорт с сайта поставщика» теперь можно вставить ссылку на товар с сайтов evrosid.ru (ЕвроСид), buskomplektnn.ru (Нижбаскомплект), tehprestige.ru (Техпрестиж) и gruppa-detaley.ru (Группа деталей). ERP подтянет название, цену поставщика, путь раздела и фотографии, а где сайт даёт описание и характеристики — и их, а вы проверите форму и сохраните товар. Вариантов у этих сайтов нет, поэтому закупка — цена с карточки (у некоторых на сайте «от …»). У Техпрестижа и Группы деталей описания нет, в него попадает только артикул поставщика.

В окне импорта теперь виден список поддерживаемых сайтов (названия — ссылки на сами сайты), а под полем ссылки сразу написано, узнан ли сайт. Ссылку можно вставлять и без «https://».

Кнопка «Подтянуть цену» в карточке товара тоже понимает ссылки на эти сайты. Как и раньше, товар заводится только когда вы нажмёте «Сохранить».',
     '2026-10-01 01:30:00', CURRENT_TIMESTAMP)
ON CONFLICT ("id") DO NOTHING;
